package org.jlinalg.cli;
import static org.junit.jupiter.api.Assertions.*;
import java.io.IOException;
import java.nio.file.*;
import java.util.concurrent.CancellationException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
class ScviModelBytesTest {
    @TempDir Path root;private int serial;
    private Path source()throws Exception{Path p=root.resolve("source-"+serial++);Files.write(p,new byte[]{(byte)0x80,2,0,(byte)0xff,13,10,7});return p;}
    private ScviModelBytes.Review review(Path p,boolean trust)throws Exception{return new ScviModelBytes.Review("synthetic-test-reviewer","self-created byte fixture;not a real model","explicitly reviewed test source",ScviText.hash(p,4096,()->{}),trust);}
    private ScviModelBytes.Prepared prepare(Path p,Path out)throws Exception{return ScviModelBytes.prepare(p,review(p,true),ScviModelRequest.Release.V1_3_0,ScviModelRequest.Family.SCANVI,out,ScviModelBytes.Limits.standard(),()->{});}
    @Test void binaryBytesArePreservedWithoutDeserialization()throws Exception{Path p=source();var a=prepare(p,root.resolve("prepared"));assertArrayEquals(Files.readAllBytes(p),Files.readAllBytes(a.model()));a.verify(()->{});assertTrue(Files.readString(a.directory().resolve("model-review.json")).contains("PREPARED_REVIEWED_MODEL_BYTES_ONLY"));assertTrue(Files.readString(a.directory().resolve("WARNINGS.md")).contains("can execute code"));assertFalse(Files.exists(a.directory().resolve("COMPLETED.json")));}
    @Test void missingOrDeclinedTrustStopsBeforeOutputOrSourceLoading()throws Exception{Path out=root.resolve("declined"),p=source();assertThrows(ScviModelBytes.TrustRequired.class,()->ScviModelBytes.prepare(root.resolve("missing"),null,ScviModelRequest.Release.V1_3_0,ScviModelRequest.Family.SCVI,out,ScviModelBytes.Limits.standard(),()->{}));assertThrows(ScviModelBytes.TrustRequired.class,()->ScviModelBytes.prepare(p,review(p,false),ScviModelRequest.Release.V1_3_0,ScviModelRequest.Family.SCVI,out,ScviModelBytes.Limits.standard(),()->{}));assertFalse(Files.exists(out));}
    @Test void reviewedHashCannotBeAttachedToDifferentBytes()throws Exception{Path p=source(),out=root.resolve("wrong");var r=new ScviModelBytes.Review("test","known source","reviewed","0".repeat(64),true);assertThrows(IOException.class,()->ScviModelBytes.prepare(p,r,ScviModelRequest.Release.V1_3_0,ScviModelRequest.Family.SCVI,out,ScviModelBytes.Limits.standard(),()->{}));assertFalse(Files.exists(out));}
    @Test void sourceAndProtectedMutationsInvalidatePreparation()throws Exception{Path p=source();var a=prepare(p,root.resolve("first"));Files.write(a.model(),new byte[]{1});assertThrows(IOException.class,()->a.verify(()->{}));Path q=source();var b=prepare(q,root.resolve("second"));Files.write(q,new byte[]{1});assertThrows(IOException.class,()->b.verify(()->{}));}
    @Test void unregisteredMembersAndRewrittenReviewsAreRejected()throws Exception{var a=prepare(source(),root.resolve("first"));Files.createDirectory(a.directory().resolve("extra"));assertThrows(IOException.class,()->a.verify(()->{}));var b=prepare(source(),root.resolve("second"));Files.writeString(b.directory().resolve("model-review.json"),"{}");assertThrows(IOException.class,()->b.verify(()->{}));}
    @Test void completeSourceAndProtectedBytesShareTheWorkspaceLimit()throws Exception{Path p=source(),out=root.resolve("tiny");assertThrows(IOException.class,()->ScviModelBytes.prepare(p,review(p,true),ScviModelRequest.Release.V1_3_0,ScviModelRequest.Family.SCVI,out,new ScviModelBytes.Limits(4096,8,16,4194304),()->{}));assertFalse(Files.exists(out.resolve("model-review.json")));}
    @Test void existingOutputAndCancellationNeverProduceCompletion()throws Exception{Path p=source(),out=Files.createDirectory(root.resolve("existing"));Files.writeString(out.resolve("keep"),"original");assertThrows(IOException.class,()->prepare(p,out));assertEquals("original",Files.readString(out.resolve("keep")));assertThrows(CancellationException.class,()->ScviModelBytes.prepare(p,review(p,true),ScviModelRequest.Release.V1_3_0,ScviModelRequest.Family.SCVI,root.resolve("cancelled"),ScviModelBytes.Limits.standard(),()->{throw new CancellationException("stop");}));}
    @Test void reviewRequiresBoundedSourceDecisionAndExactDigest(){assertThrows(IllegalArgumentException.class,()->new ScviModelBytes.Review("","origin","decision","a".repeat(64),true));assertThrows(IllegalArgumentException.class,()->new ScviModelBytes.Review("reviewer","origin","decision","bad",true));}
}
